import { MessageActions } from './Message';
import { RequestMessage } from './RequestMessage';

export interface CustomAvatarMenuItemOption<T> {
  label: string;
  value: T;
}
export interface CustomAvatarMenuItem<T = any> {
  name: string;
  label: string;
  isSwitch: boolean;
  options?: CustomAvatarMenuItemOption<T>[];
  defaultOptionValue?: T;
  value?: T;
  ariaLabel: string;
}
export interface CustomAvatarMenu {
  isActive: boolean;
  items: CustomAvatarMenuItem[];
}
export class CustomAvatarMenuRequestMessage extends RequestMessage {
  customAvatarMenu: CustomAvatarMenu;

  constructor(customAvatarMenu: CustomAvatarMenu) {
    super(MessageActions.CustomAvatarMenuRequest);
    this.customAvatarMenu = customAvatarMenu;
  }
}
