import { MessageActions } from './Message';
import { RequestMessage } from './RequestMessage';

export enum HeaderItemType {
  Popover = 'popover',
}

export abstract class HeaderItemBase {
  abstract type: HeaderItemType;
  abstract name: string;
  abstract label: string;
  abstract ariaLabel?: string;
}

export interface PopoverHeaderItem extends HeaderItemBase {
  type: HeaderItemType.Popover;
  showArrow: boolean;
}

export type HeaderItem = PopoverHeaderItem;

export class CustomHeaderItemsRequestMessage extends RequestMessage {
  constructor(public items: HeaderItem[]) {
    super(MessageActions.CustomHeaderItemsRequest);
  }
}
