import { useEffect } from 'react';
import { useHistory } from 'react-router-dom';
import { AppNavigationMessage } from '../messages/AppNavigationMessage';
import { isIFrame, getPortalHost } from '../utility/utils';
import { PortalMessageService } from '../services/PortalMessageService';
import * as H from 'history';

export const useDomHistoryMonitor = () => {
  const history: H.History = useHistory();
  const portalHost = getPortalHost();

  useEffect(() => {
    const sendNotificationToPortal = (path: string, location?: H.Location) => {
      const message = new AppNavigationMessage();
      message.url = path;
      message.location = location;
      if (isIFrame()) {
        PortalMessageService.getInstance().sendMessageToPortal(message);
      }
    };

    sendNotificationToPortal(history.location.pathname, history.location);
    history.listen((event: any) => {
      sendNotificationToPortal(event.pathname, event);
    });
  }, [history, portalHost]);
};
