import { MessageActions } from '../messages/Message';
import { MfeActivityMessage } from '../messages/MfeActivityMessage';
import throttle from 'lodash.throttle';
import { BackdropInfo } from '../messages/BackdropInfo';
import { EnablePortalBackdropRequestMessage } from '../messages/EnablePortalBackdropRequestMessage';
import { PortalMessageService } from '../services/PortalMessageService';
import { PreferencesChangeRequestMessage } from '../messages/PreferencesChangeRequestMessage';
const IFRAME_PORTAL_URL = 'portal-host';

/**
 * TODO: Create environment interface and export it as part of the library API
 */
declare global {
  interface Window {
    env: any;
  }
}

export const isPortalMessage = (action: string): boolean => {
  return !!Object.keys(MessageActions).find((key) => MessageActions[key as keyof typeof MessageActions] === action);
};

export const isIFrame = (): boolean => {
  return window.parent !== window.self;
};

export const getPortalHost = (): string => {
  let parentUrl: string = '';

  try {
    let params = new URLSearchParams(window.location.search);
    let portalHostUrl = document.referrer || params.get(IFRAME_PORTAL_URL) || '';

    parentUrl = (
      window.location !== window.parent.location
        ? window.location.ancestorOrigins?.[window.location.ancestorOrigins.length - 1] || portalHostUrl
        : document.location.href
    ).replace(/\/$/, '');
  } catch (e) {
    console.error('[PortalMessageService] Could not resolve portal host.');
  }

  return window?.env?.PORTAL_HOST || parentUrl;
};

export const getParentPortalHost = (): string => {
  let parentPortalHost: string = '';

  try {
    let parentParams = new URLSearchParams(window.parent.location.search);
    parentPortalHost = document.referrer || parentParams.get(IFRAME_PORTAL_URL) || '';
  } catch (e) {
    console.error('[PortalMessageService] Could not resolve parent portal host.');
  }

  return parentPortalHost;
};

export const getIncomingTheme = (): string => {
  console.error(
    `getIncomingTheme is deprecated, please use the ThemeSwitch messages instead. 
     Please refer to the documentation under Portal User Menu Selection for the new way to handle theming`
  );
  const themes = ['light', 'dark'];
  const { searchParams } = new URL(window.location.href);
  const paramTheme = searchParams.get('theme')?.toLowerCase() || themes[0];
  return themes.find((shade) => paramTheme === shade) ? paramTheme : themes[0];
};

export const getIconSrc = (iconsUrl: string, icon: string): string => {
  let iconSrc = `${iconsUrl}/ui/${icon}.svg`;

  if (icon.toLowerCase().startsWith('nav')) {
    iconSrc = `${iconsUrl}/nav/${icon}.svg`;
  } else if (icon.toLowerCase().startsWith('app')) {
    iconSrc = `${iconsUrl}/app/${icon}.svg`;
  } else if (icon.toLowerCase().startsWith('http')) {
    iconSrc = icon;
  }

  return iconSrc;
};

export const registerEventListeners = () => {
  const activityMessage = new MfeActivityMessage();
  if (isIFrame()) {
    const handleEvent = throttle(() => {
      window.top!.postMessage(activityMessage, getPortalHost());
    }, 30000);

    const defaultEvents = [
      'mousemove',
      'keydown',
      'wheel',
      'DOMMouseScroll',
      'mousewheel',
      'mousedown',
      'touchstart',
      'touchmove',
      'MSPointerDown',
      'MSPointerMove',
      'visibilitychange',
    ];
    defaultEvents.forEach((e) => {
      document.addEventListener(e, handleEvent, {
        capture: true,
        passive: true,
      });
    });
  }
};

export const TIMEOUT: number = 50;

export const backdropMessage = (enablePortalBackdropRequestMessage: EnablePortalBackdropRequestMessage) => {
  PortalMessageService.getInstance().sendMessageToPortal(enablePortalBackdropRequestMessage);
};

export const sendPreferencesChangeRequestMessage = async (
  preferencesChangeRequestMessage: PreferencesChangeRequestMessage
) => {
  PortalMessageService.getInstance().sendMessageToPortal(preferencesChangeRequestMessage);
};

export const onModelOpen = (timeout: number = TIMEOUT) => {
  return () => {
    backdropMessage(getRequestMessage(timeout, Date.now(), true));
  };
};

export const onModelClose = (timeout: number = TIMEOUT) => {
  backdropMessage(getRequestMessage(timeout, Date.now(), false));
};

export const getRequestMessage = (
  timeout: number,
  timestamp: number,
  enabled: boolean
): EnablePortalBackdropRequestMessage => {
  const info: BackdropInfo = { timeout, timestamp, enabled };
  const enablePortalBackdropRequestMessage = new EnablePortalBackdropRequestMessage(info);
  return enablePortalBackdropRequestMessage;
};
