import { RequestMessage } from './RequestMessage';
import { MessageActions } from './Message';

export type BreadcrumbInfo = {
  title: string;
  pathname: string;
  id: string;
};

export class Breadcrumbs extends RequestMessage {
  data: BreadcrumbInfo[];

  constructor(data: BreadcrumbInfo[]) {
    /* DW: TS is transpiling this as an || which results in a missing branch covered. no idea why. */
    /* istanbul ignore next */

    super(MessageActions.Breadcrumbs);
    this.data = data;
  }
}
