const generateScrollStyles = (theme) => ({
    scrollbarWidth: 'none',
    scrollbarColor: Tokens.colors[`${theme.palette.type}Theme`].materialTableScrollColor,
    '&::-webkit-scrollbar': {
        display: 'none',
        width: theme.spacing(0.75),
        height: theme.spacing(0.75),
        borderRadius: theme.spacing(2.5),
    },
    '&::-webkit-scrollbar-thumb': {
        backgroundColor: Tokens.colors[`${theme.palette.type}Theme`].materialTableScrollColor,
        borderRadius: theme.spacing(2.5),
        borderColor: 'transparent',
    },
    '& ::-webkit-scrollbar-corner': { background: 'transparent' },
    '&:hover': {
        backgroundColor: Tokens.colors[`${theme.palette.type}Theme`].materialTableScrollBackground,
        scrollbarWidth: 'thin',
        '&::-webkit-scrollbar': {
            display: 'block',
        },
    },
});

export { generateScrollStyles as g };
