import { Message } from '../messages/Message';
import { isIFrame, getPortalHost, getParentPortalHost } from '../utility/utils';

class DeferredDataRequest<T> {
  originalRequest: Message;
  promise: Promise<any>;
  portalHost: string;
  resolve: (value?: T) => void;
  reject: (reason?: any) => void;

  constructor() {
    this.promise = new Promise<T>((resolve?, reject?) => {
      (this.resolve as any) = resolve;
      this.reject = reject;
    });
  }
}

export type MessageService = {
  sendMessageToPortal: (message: Message) => void;
  relayMessageToParent: (message: Message) => void;
  requestDataFromPortal: <T extends unknown>(request: Message) => Promise<T>;
  registerListener: (perpetualListener: (messageData: any) => void) => void;
  destroy: () => void;
};

export class PortalMessageService implements MessageService {
  private static _instance?: MessageService;
  private _messageID = 1;
  private _dataRequests = new Map<string, DeferredDataRequest<any>>();
  private _listener: (messageData: any) => void;

  static getInstance = () => {
    if (!isIFrame()) {
      throw new Error('Not available in standalone mode');
    } else if (!PortalMessageService._instance) {
      PortalMessageService._instance = new PortalMessageService();
    }
    return PortalMessageService._instance;
  };

  private constructor() {
    window.addEventListener('message', this.messageReceived);
  }

  destroy() {
    delete PortalMessageService._instance;
    window.removeEventListener('message', this.messageReceived);
  }

  private messageReceived = (messageEvent: any) => {
    const { origin } = messageEvent;
    const messageData = messageEvent.data;
    if (!messageData || !messageData.messageId) {
      // TODO: logging?
      return;
    }

    const { messageId } = messageData;
    const request = this._dataRequests.get(messageId);
    if (request && request.portalHost === origin) {
      if (messageData.status === 200) {
        request.resolve(messageData);
      } else {
        request.reject(`Portal returned error: ${messageData.message}`);
      }
    }
    if (this._listener) {
      this._listener.call(this, messageData);
    }
  };

  private getNewMessageId = (incomingMessageID: string) => {
    // default message id if not provided
    let currentMessageId = incomingMessageID;
    if (!incomingMessageID) {
      currentMessageId = this._messageID.toString();
      this._messageID += 1;
    }
    return currentMessageId;
  };

  registerListener = (perpetualListener: (messageData: any) => void) => {
    this._listener = perpetualListener;
  };

  sendMessageToPortal = (message: Message) => {
    const portalHost = getPortalHost();
    const currentMessageId = this.getNewMessageId(message.messageId);

    message.messageId = currentMessageId;

    window.parent.postMessage(message, portalHost);
  };

  relayMessageToParent = (message: Message) => {
    const parentHost = getParentPortalHost();
    message.messageId = this.getNewMessageId(message.messageId);
    window.parent.postMessage(message, parentHost);
  };

  requestDataFromPortal = <T extends unknown>(request: Message) => {
    const portalHost = getPortalHost();
    const currentMessageId = this.getNewMessageId(request.messageId);
    const storedRequest = new DeferredDataRequest<T>();

    request.messageId = currentMessageId;
    storedRequest.originalRequest = request;
    storedRequest.portalHost = portalHost;

    this._dataRequests.set(currentMessageId, storedRequest);
    window.parent.postMessage(request, portalHost);
    return storedRequest.promise;
  };
}
