import { RequestMessage } from './RequestMessage';
import { MessageActions } from './Message';
import * as H from 'history';

export class AppNavigationDeepLink extends RequestMessage {
  url: string;
  appNamespace: string;
  location: H.Location | undefined;

  constructor(destinationApp: string, destinationRoute: string, location?: H.Location) {
    /* DW: TS is transpiling this as an || which results in a missing branch covered. no idea why. */
    /* istanbul ignore next */

    super(MessageActions.DeepLink);
    this.url = destinationRoute;
    this.appNamespace = destinationApp;
    this.location = location;
  }
}
