import { MessageActions } from './Message';
import { ResponseMessage } from './ResponseMessage';

export interface TargetElement {
  position: Pick<DOMRect, 'right' | 'left'>;
}

export interface CustomHeaderItemResponse<T = any> {
  name: string;
  target: TargetElement;
  value?: T;
}

export class CustomHeaderItemsResponseMessage<T = any> extends ResponseMessage implements CustomHeaderItemResponse {
  constructor(public name: string, public target: TargetElement, public value?: T) {
    super(MessageActions.CustomHeaderItemsResponse);
  }
}
