import countryToCurrency from 'country-to-currency';
import { DateTime, DateTimeFormatOptions, Settings, Zone } from 'luxon';
import { localizeDebug } from './localizationFlag';

// Definition of each of the data types accepted
export const NUMBER_FORMATTER: 'number' = 'number';
export const CURRENCY_FORMATTER: 'currency' = 'currency';
export const DATE_FORMATTER: 'date' = 'date';
export const TIME_FORMATTER: 'time' = 'time';

// Formatting options for dates
export const dateOptions = {
  DATE_SHORT: DateTime.DATE_SHORT,
  DATE_MED: DateTime.DATE_MED,
  DATE_MED_WITH_WEEKDAY: DateTime.DATE_MED_WITH_WEEKDAY,
  DATE_FULL: DateTime.DATE_FULL,
  DATE_HUGE: DateTime.DATE_HUGE,
  DATETIME_SHORT: DateTime.DATETIME_SHORT,
  DATETIME_MED: DateTime.DATETIME_MED,
  DATETIME_FULL: DateTime.DATETIME_FULL,
  DATETIME_HUGE: DateTime.DATETIME_HUGE,
  DATETIME_SHORT_WITH_SECONDS: DateTime.DATETIME_SHORT_WITH_SECONDS,
  DATETIME_MED_WITH_SECONDS: DateTime.DATETIME_MED_WITH_SECONDS,
  DATETIME_FULL_WITH_SECONDS: DateTime.DATETIME_FULL_WITH_SECONDS,
  DATETIME_HUGE_WITH_SECONDS: DateTime.DATETIME_HUGE_WITH_SECONDS,
};

// Formatting options for time
export const timeOptions = {
  TIME_SIMPLE: DateTime.TIME_SIMPLE,
  TIME_WITH_SECONDS: DateTime.TIME_WITH_SECONDS,
  TIME_WITH_SHORT_OFFSET: DateTime.TIME_WITH_SHORT_OFFSET,
  TIME_WITH_LONG_OFFSET: DateTime.TIME_WITH_LONG_OFFSET,
  TIME_24_SIMPLE: DateTime.TIME_24_SIMPLE,
  TIME_24_WITH_SECONDS: DateTime.TIME_24_WITH_SECONDS,
  TIME_24_WITH_SHORT_OFFSET: DateTime.TIME_24_WITH_SHORT_OFFSET,
  TIME_24_WITH_LONG_OFFSET: DateTime.TIME_24_WITH_LONG_OFFSET,
  TIME_12_NUMERIC: { hour: 'numeric' } as DateTimeFormatOptions,
  TIME_12_NUMERIC_PADDED: { hour: '2-digit' } as DateTimeFormatOptions,
  TIME_24_NUMERIC: { hour: 'numeric', hour12: false } as DateTimeFormatOptions,
  TIME_24_NUMERIC_PADDED: { hour: '2-digit', hour12: false } as DateTimeFormatOptions,
};

// Default locales
export const defaultLocales = {
  es: 'es-ES', // Spanish defaults to Spain
  en: 'en-US', // English defaults to US
  ja: 'ja-JA', // Japanese defaults to Japan
  zh: 'zh-CN', // Chinese defaults to Mainland China
  fr: 'fr-FR', // French defaults to France
  de: 'de-DE', // German defaults to Germany
};

// Optional parameters typing depending on type
export interface DateProperties {
  region?: string;
  language?: string;
  timeZone?: string | Zone;
  options?: DateTimeFormatOptions;
}
export interface TimeProperties {
  region?: string;
  language?: string;
  options: DateTimeFormatOptions;
}
export interface NumberProperties {
  region?: string;
  language?: string;
  options?: Intl.NumberFormatOptions;
}
export interface CurrencyProperties {
  region?: string;
  language?: string;
  options?: Intl.NumberFormatOptions;
}

export type DateTimeFormatter = (date: string | Date) => string;
export type NumberCurrencyFormatter = (number: string | number) => string;

export type FormatterDefinitionType<T> = T extends 'time'
  ? TimeProperties
  : T extends 'date'
  ? DateProperties
  : T extends 'number'
  ? NumberProperties
  : T extends 'currency'
  ? CurrencyProperties
  : never;

export type FormatterReturnType<T> = T extends 'time'
  ? DateTimeFormatter
  : T extends 'date'
  ? DateTimeFormatter
  : T extends 'number'
  ? NumberCurrencyFormatter
  : T extends 'currency'
  ? NumberCurrencyFormatter
  : never;

// Get the locale of the current environment
function getEnviromentLocale(): string {
  if (window.navigator.languages) {
    let [enviromentLocaleObtained] = window.navigator.languages;
    return enviromentLocaleObtained;
  } else {
    return (window.navigator as any).userLanguage || window.navigator.language;
  }
}

// Decide which will be the locale
function getLocale(language?: string, region?: string): string {
  if (!!language && !!region) {
    // If language and region return the locale
    return `${language.toLowerCase()}-${region.toUpperCase()}`;
  } else if (!!language && !region && !!defaultLocales[language.toLowerCase() as keyof typeof defaultLocales]) {
    // If just language return language plus default region as locale
    return `${defaultLocales[language.toLowerCase() as keyof typeof defaultLocales]}`;
  } else {
    // If none of the above conditions use enviroment detected locale
    localizeDebug(
      `Formatting factory locale was set to the one detected (${getEnviromentLocale()}) as not a valid locale was specified`
    );
    return getEnviromentLocale();
  }
}

type FormatterType = 'date' | 'time' | 'currency' | 'number';

export function getTimeFormatterFunction(definition: FormatterDefinitionType<'time'>): DateTimeFormatter {
  return getFormatterFunction(TIME_FORMATTER, definition);
}

export function getDateFormatterFunction(definition: FormatterDefinitionType<'date'>): DateTimeFormatter {
  return getFormatterFunction(DATE_FORMATTER, definition);
}

export function getNumberFormatterFunction(definition: FormatterDefinitionType<'number'>): NumberCurrencyFormatter {
  return getFormatterFunction(NUMBER_FORMATTER, definition);
}

export function getCurrencyFormatterFunction(definition: FormatterDefinitionType<'currency'>): NumberCurrencyFormatter {
  return getFormatterFunction(CURRENCY_FORMATTER, definition);
}

export function getFormatterFunction<T extends FormatterType>(
  type: T,
  definition: FormatterDefinitionType<T>
): FormatterReturnType<T> {
  // Destructure parameters
  let { language, region, options } = definition;
  let timeZone: string | Zone = Settings.defaultZone;

  if ((definition as DateProperties).timeZone) {
    timeZone = (definition as DateProperties).timeZone!;
  }

  // Get locale
  let locale: string = getLocale(language, region);

  options = options || {};

  // Function to localize numbers and currency
  const localizeNumberCurrency: NumberCurrencyFormatter = (number) => {
    // Desctructure options
    let {
      currency,
      localeMatcher,
      currencyDisplay,
      currencySign,
      maximumFractionDigits,
      maximumSignificantDigits,
      minimumSignificantDigits,
      minimumIntegerDigits,
      style,
      minimumFractionDigits,
      useGrouping,
    } = options as Intl.NumberFormatOptions;

    // If number is string then convert to float
    if (typeof number === 'string') number = parseFloat(number);

    // If no currency is provided then get it from locale
    if (!currency && type === CURRENCY_FORMATTER) {
      currency = countryToCurrency[locale.split('-')[1].toUpperCase() as keyof typeof countryToCurrency];
    }

    // Return formatted number
    return number.toLocaleString(locale, {
      currency: currency,
      useGrouping: useGrouping,
      minimumSignificantDigits: minimumSignificantDigits,
      minimumIntegerDigits: minimumIntegerDigits,
      minimumFractionDigits: minimumFractionDigits,
      maximumSignificantDigits: maximumSignificantDigits,
      maximumFractionDigits: maximumFractionDigits,
      currencySign: currencySign,
      currencyDisplay: currencyDisplay,
      localeMatcher: localeMatcher,
      style: type === CURRENCY_FORMATTER ? CURRENCY_FORMATTER : style,
    });
  };

  // Function to localize dates and time
  const localizeDateTime: DateTimeFormatter = (date) => {
    // Check if unix epoch supporting numbers and strings
    const processedDate = new Date(date);
    localizeDebug(`Input date for formatting after being processed by javascript date object: ${processedDate}`);
    return DateTime.fromJSDate(processedDate)
      .setLocale(locale)
      .setZone(timeZone)
      .toLocaleString(options as DateTimeFormatOptions);
  };

  // Decide the type of function to be used
  switch (type) {
    case NUMBER_FORMATTER:
      return localizeNumberCurrency as FormatterReturnType<T>;
    case DATE_FORMATTER:
      return localizeDateTime as FormatterReturnType<T>;
    case TIME_FORMATTER:
      return localizeDateTime as FormatterReturnType<T>;
    case CURRENCY_FORMATTER:
      return localizeNumberCurrency as FormatterReturnType<T>;
    default:
      throw new Error('A type for the data to be formatted has to be specified');
  }
}
